def add(kind,text,why,family,p,**kw):
 items.append(dict(type=kind,text=text,explanation=why,page=f'মূল ধারণা: বই পৃ. {p}; নিজস্ব অনুশীলনী, বোর্ড প্রশ্ন নয়',difficulty=kw.pop('difficulty','MEDIUM'),**kw));review.append(dict(index=len(items),kind=kind,family=family,textbookPages=p,originalPractice=True,teacherApproved=False))
def mcq(q,a,w,why,family,p):
 assert len(w)==3 and len(set([a,*w]))==4,(q,a,w)
 pos=sum(x['type']=='MCQ' for x in items)%4;opts=list(w);opts.insert(pos,a);add('MCQ',q,why,family,p,options=dict(zip('ABCD',opts)),correct='ABCD'[pos])
def sq(q,a,f,p):add('SQ',q,a,f,p)
def cq(stem,parts,f,p):
 assert len(parts)==4
 add('CQ',stem,'উপপ্রশ্নভিত্তিক নমুনা উত্তর; স্বাধীন শিক্ষক যাচাই বাকি।',f,p,difficulty='HARD',parts=[dict(label=label,question=q,solution=a,marks=n) for n,(label,(q,a)) in enumerate(zip('কখগঘ',parts),1)])
def ratio(x):
 x=F(x);return str(x.numerator) if x.denominator==1 else f'{x.numerator}/{x.denominator}'
