 probes=[('প্রোটনসংখ্যা কত?',z,[z+1,z+2,0],f'p=Z={z}।'),('নিউট্রনসংখ্যা কত?',neutron,[a,a+z,neutron+1],f'n=A−Z={a}−{z}={neutron}।'),('ইলেকট্রনসংখ্যা কত?',e,[e+1,e+2,0],f'চার্জ/e₀=p−e; e={z}−({chargeText})={e}।'),('নিউক্লিয়নের মোট সংখ্যা কত?',a,[neutron,a+z,a+1],f'নিউক্লিয়ন=p+n=A={a}; ইলেকট্রন এতে ধরা হয় না।'),('ইলেকট্রনসহ p+n+e মোট কত?',a+e,[a,a+e+1,a+e+2],f'p+n+e=A+e={a}+{e}={a+e}।')]
 for j,(q,ans,w,why) in enumerate(probes,1):numeric(stem+'\n\n'+q,ans,w,why,f'nuclide-probe-{j}', '40–41');meta(variant=n,modelInputs=dict(symbol=symbol,Z=z,A=a,charge=charge),hypotheticalData=True)
 cq(stem,[('ভরসংখ্যা কী?','নিউক্লিয়াসের প্রোটন ও নিউট্রনের মোট সংখ্যা A।'),('নিট চার্জ বদলালে মৌলের পরিচয় অবশ্যই বদলায় না কেন?','ইলেকট্রন গ্রহণ/ত্যাগে চার্জ বদলাতে পারে, কিন্তু প্রোটনসংখ্যা অপরিবর্তিত থাকলে মৌল অপরিবর্তিত।'),('চিত্র থেকে p,n,e হিসাব করো।',f'p={z};n={a}−{z}={neutron};e={z}−({chargeText})={e}।'),('একই মৌলের A+1 ভরের নিরপেক্ষ পরমাণুর সঙ্গে তুলনা করো।',f'মূল কণায় p={z},n={neutron},e={e}। তুলনীয় পরমাণুতে p={z},n={neutron+1},e={z},A={a+1}। Z একই বলে একই মৌল; A ভিন্ন বলে আইসোটোপ। প্রাকৃতিক প্রাচুর্য/স্থিতিশীলতা এই শর্ত থেকে জানা যায় না।')],'nuclide-cq','40–41,50–51');meta(variant=n,hypotheticalData=True)
