 probes=[('X-এর গড় আপেক্ষিক পারমাণবিক ভর কত?',ratio(avg),[ratio(avg+3),str(low),str(high)],f'Ar=({low}×{percent}+{high}×{other})/100={ratio(avg)}; এককবিহীন।'),('হালকা আইসোটোপে নিউট্রন কত?',str(low-z),[str(low),str(high-z),str(low-z+1)],f'n={low}−{z}={low-z}।'),('ভারী আইসোটোপে নিউট্রন কত?',str(high-z),[str(high),str(low-z),str(high-z+1)],f'n={high}−{z}={high-z}।'),('এ মডেলের 10000টি পরমাণুতে প্রাচুর্য-অনুপাত অনুযায়ী হালকার প্রত্যাশিত সংখ্যা কত?',str(percent*100),[str(percent*100-100),str(percent),str(percent*100+100)],f'প্রত্যাশিত সংখ্যা=10000×{percent}/100={percent*100}; ক্ষুদ্র বাস্তব নমুনার নিশ্চিত গণনা নয়।'),('হালকার ভগ্নাংশ f হলে সঠিক গড়ের সমীকরণ কোনটি?',f'{low}f+{high}(1−f)={ratio(avg)}',[f'{high}f+{low}(1−f)={ratio(avg)}',f'{low}f+{high}f={ratio(avg)}',f'{low}+{high}={ratio(avg)}'],'হালকার ভগ্নাংশ f, ভারীর 1−f; নিজ নিজ ভর দিয়ে গুণ করে যোগ করতে হবে।')]
 for j,(q,ans,w,why) in enumerate(probes,1):mcq(stem+'\n\n'+q,ans,w,why,f'isotope-probe-{j}','50–53');meta(variant=n,hypotheticalData=True,modelInputs=dict(Z=z,low=low,high=high,percentLight=percent))
 cq(stem,[('আইসোটোপ কী?','একই Z কিন্তু ভিন্ন A-এর পরমাণু।'),('এখানে সরল গড় ব্যবহারের শর্ত কী?',('এ মডেলে প্রাচুর্য 50% ও 50%, তাই সরল গড় ও ভারযুক্ত গড় মেলে।' if percent==50 else 'প্রাচুর্য সমান হলেই সরল গড় চলে; এখানে অসমান বলে ভারযুক্ত গড় প্রয়োজন।')),('গড় আপেক্ষিক ভর এবং দুই আইসোটোপের নিউট্রনসংখ্যা নির্ণয় করো।',f'Ar={ratio(avg)};nহালকা={low}−{z}={low-z};nভারী={high}−{z}={high-z}।'),('শুধু গড় ও দুই ভর জানা থাকলে হালকার প্রাচুর্য পুনরুদ্ধার করো এবং ফলের সীমা লেখো।',f'f=({high}−{ratio(avg)})/({high}−{low})={percent}/100;হালকা {percent}%,ভারী {other}%। কেবল দুটি আইসোটোপ এবং নির্দিষ্ট আনুমানিক ভর ধরে সমাধান; তৃতীয় আইসোটোপ থাকলে একই সমীকরণ যথেষ্ট নয়।')],'isotope-cq','50–53');meta(variant=n,hypotheticalData=True)
